class ThemeSwitcher {
  constructor() {
    ((this.themeColorMeta = document.getElementById("theme-color-meta")),
      (this.body = document.body),
      (this.storageKey = "theme-preference"),
      (this.themes = { LIGHT: "sadakiyo5", DARK: "trash-panda" }));
  }
  updateThemeColor() {
    var e;
    this.themeColorMeta &&
      ((e = getComputedStyle(this.body).getPropertyValue("--bg-meta").trim()),
      this.themeColorMeta.setAttribute("content", e));
  }
  init() {
    var e = localStorage.getItem(this.storageKey);
    (e && Object.values(this.themes).includes(e)
      ? this.setTheme(e)
      : ((e = window.matchMedia("(prefers-color-scheme: dark)").matches),
        this.setTheme(e ? this.themes.DARK : this.themes.LIGHT)),
      this.updateThemeColor());
  }
  toggleTheme() {
    var e =
      this.getCurrentTheme() === this.themes.DARK
        ? this.themes.LIGHT
        : this.themes.DARK;
    (this.setTheme(e), setTimeout(() => this.updateThemeColor(), 0));
  }
  setTheme(e) {
    (this.body.classList.remove(...Object.values(this.themes)),
      this.body.classList.add(e),
      localStorage.setItem(this.storageKey, e));
  }
  getCurrentTheme() {
    return this.body.classList.contains(this.themes.DARK)
      ? this.themes.DARK
      : this.themes.LIGHT;
  }
}
